import json, sys, random, statistics

args = json.loads(sys.stdin.read().strip() or "{}")
task = args["task"]
rng = random.Random(args.get("seed", 1))
planted = {}

def n1(x):
    return round(x, 1)

def noisy(x, p=0.015):
    return x * (1.0 + rng.uniform(-p, p))

def emit(lines, name):
    open(name, "w").write("\n".join(lines) + "\n")

def highest_linear(loads, dens, tol=0.15):
    slope = dens[0] / loads[0]
    best = loads[0]
    for L, D in zip(loads, dens):
        if abs(D / (slope * L) - 1.0) <= tol:
            best = L
    return best

if task == "g1":
    loads = [1.0, 2.5, 5.0, 10.0, 20.0, 40.0]
    gap = []
    mdm = []
    for L in loads:
        if L <= 10.0:
            g = 5000.0 * L
        elif L == 20.0:
            g = 57000.0
        else:
            g = 60000.0
        gap.append(n1(noisy(g)))
        mdm.append(n1(noisy(1200.0 * L)))
    lines = ["load_ug,GAPDH_density,MDM2_density"]
    for L, g, m in zip(loads, gap, mdm):
        lines.append("%s,%s,%s" % (L, g, m))
    emit(lines, "antibody_dilution_series.csv")
    hg = highest_linear(loads, gap)
    hm = highest_linear(loads, mdm)
    planted["gapdh_highest_linear_load"] = hg
    planted["mdm2_highest_linear_load"] = hm
    planted["gapdh_loses_proportionality"] = hg < loads[-1]
    planted["mdm2_loses_proportionality"] = hm < loads[-1]

elif task == "g2":
    conds = ["Normoxia", "Hypoxia_24h", "Hypoxia_48h"]
    ldha = {"Normoxia": 1.0, "Hypoxia_24h": 1.9, "Hypoxia_48h": 2.6}
    gapdh = {"Normoxia": 1.0, "Hypoxia_24h": 0.75, "Hypoxia_48h": 0.62}
    actb = {"Normoxia": 1.0, "Hypoxia_24h": 1.0, "Hypoxia_48h": 1.0}
    meas = {}
    lines = ["replicate,condition,protein,density"]
    for r in (1, 2, 3):
        for c in conds:
            lf = 1.0 + rng.uniform(-0.08, 0.08)
            vals = {
                "LDHA": n1(noisy(lf * ldha[c] * 22000.0)),
                "GAPDH": n1(noisy(lf * gapdh[c] * 48000.0)),
                "ACTB": n1(noisy(lf * actb[c] * 52000.0)),
                "TotalProteinStain": n1(noisy(lf * 900000.0)),
            }
            for p, v in vals.items():
                meas[(r, c, p)] = v
                lines.append("R%d,%s,%s,%s" % (r, c, p, v))
    emit(lines, "hypoxia_panel.csv")
    def per_tp(r, c, p):
        return meas[(r, c, p)] / meas[(r, c, "TotalProteinStain")]
    def changed(p):
        base = statistics.fmean([per_tp(r, "Normoxia", p) for r in (1, 2, 3)])
        late = statistics.fmean([per_tp(r, "Hypoxia_48h", p) for r in (1, 2, 3)])
        return abs(late / base - 1.0) > 0.15
    def ldha_fold(c):
        return statistics.fmean([per_tp(r, c, "LDHA") / per_tp(r, "Normoxia", "LDHA") for r in (1, 2, 3)])
    planted["gapdh_changes"] = changed("GAPDH")
    planted["actb_changes"] = changed("ACTB")
    planted["ldha_fold_48h"] = ldha_fold("Hypoxia_48h")
    planted["ldha_fold_24h"] = ldha_fold("Hypoxia_24h")

elif task == "g3":
    lf = {"Control": 0.60, "Treated": 1.50}
    bgpx = {"Control": 8.0, "Treated": 2.0}
    area = {"CDKN1A": 900, "CCND1": 1200, "GAPDH": 3000}
    ab = {"CDKN1A": {"Control": 1.0, "Treated": 0.8}, "CCND1": {"Control": 1.0, "Treated": 2.0}}
    scale = {"CDKN1A": 20000.0, "CCND1": 15000.0, "GAPDH": 45000.0}
    raw = {}
    sub = {}
    lines = ["lane,condition,protein,raw_band_density,band_area_px,local_background_per_px"]
    for i, c in enumerate(["Control", "Treated"], 1):
        for p in ("CDKN1A", "CCND1", "GAPDH"):
            a = ab[p][c] if p in ab else 1.0
            signal = lf[c] * a * scale[p]
            bg = bgpx[c] * area[p]
            r = n1(noisy(signal) + bg)
            raw[(c, p)] = r
            sub[(c, p)] = r - bg
            lines.append("L%d,%s,%s,%s,%d,%s" % (i, c, p, r, area[p], bgpx[c]))
    emit(lines, "background_blot.csv")
    def norm_fold(p):
        a = sub[("Treated", p)] / sub[("Treated", "GAPDH")]
        b = sub[("Control", p)] / sub[("Control", "GAPDH")]
        return a / b
    def disagree(p):
        return (raw[("Treated", p)] / raw[("Control", p)] > 1.0) != (norm_fold(p) > 1.0)
    planted["cdkn1a_fold"] = norm_fold("CDKN1A")
    planted["ccnd1_fold"] = norm_fold("CCND1")
    planted["cdkn1a_disagrees"] = disagree("CDKN1A")
    planted["ccnd1_disagrees"] = disagree("CCND1")

elif task == "g4":
    gain = {1: 0.8, 2: 1.0, 3: 1.4, 4: 1.1}
    folds = {1: 2.1, 2: 2.4, 3: 3.0, 4: 1.8}
    meas = {}
    lines = ["replicate,condition,protein,raw_intensity"]
    for r in (1, 2, 3, 4):
        for c, f in (("Control", 1.0), ("Treated", folds[r])):
            lfv = 1.0 + rng.uniform(-0.10, 0.10)
            bax = n1(noisy(gain[r] * f * lfv * 18000.0))
            gap = n1(noisy(lfv * 46000.0))
            if not (r == 3 and c == "Treated"):
                meas[(r, c, "BAX")] = bax
                lines.append("R%d,%s,BAX,%s" % (r, c, bax))
            meas[(r, c, "GAPDH")] = gap
            lines.append("R%d,%s,GAPDH,%s" % (r, c, gap))
    emit(lines, "bax_four_repeats.csv")
    usable = []
    missing = []
    for r in (1, 2, 3, 4):
        ok = all((r, c, p) in meas for c in ("Control", "Treated") for p in ("BAX", "GAPDH"))
        if ok:
            a = meas[(r, "Treated", "BAX")] / meas[(r, "Treated", "GAPDH")]
            b = meas[(r, "Control", "BAX")] / meas[(r, "Control", "GAPDH")]
            usable.append(a / b)
        else:
            missing.append("R%d" % r)
    lc_missing = [r for r in (1, 2, 3, 4) if not all((r, c, "GAPDH") in meas for c in ("Control", "Treated"))]
    planted["incomplete_replicate"] = missing[0] if missing else "none"
    planted["all_target_bands_detected"] = len(missing) == 0
    planted["all_loading_control_bands_detected"] = len(lc_missing) == 0
    planted["mean_fold_usable"] = statistics.fmean(usable)
    planted["n_usable"] = float(len(usable))

elif task == "g5":
    gain = {1: 0.5, 2: 1.0, 3: 2.5}
    fx = {1: 3.2, 2: 2.0, 3: 1.4}
    fy = {1: 1.8, 2: 1.8, 3: 1.8}
    meas = {}
    lines = ["replicate,condition,protein,normalized_value"]
    for r in (1, 2, 3):
        for p, folds, base in (("STAT3", fx, 1.0), ("TUBB", fy, 0.8)):
            for c, f in (("Control", 1.0), ("Treated", folds[r])):
                v = round(noisy(gain[r] * base * f, 0.03), 4)
                meas[(r, c, p)] = v
                lines.append("R%d,%s,%s,%s" % (r, c, p, v))
    emit(lines, "two_protein_replicates.csv")
    def per_rep(p):
        return [meas[(r, "Treated", p)] / meas[(r, "Control", p)] for r in (1, 2, 3)]
    def pooled(p):
        t = statistics.fmean([meas[(r, "Treated", p)] for r in (1, 2, 3)])
        c = statistics.fmean([meas[(r, "Control", p)] for r in (1, 2, 3)])
        return t / c
    for p, key in (("STAT3", "stat3"), ("TUBB", "tubb")):
        m = statistics.fmean(per_rep(p))
        planted[key + "_mean_fold"] = m
        planted[key + "_order_matters"] = abs(pooled(p) / m - 1.0) > 0.10

elif task == "g6":
    reps = [1, 2, 3, 4, 5]
    gain = {1: 0.9, 2: 1.2, 3: 1.0, 4: 1.5, 5: 0.8}
    f1 = {1: 2.1, 2: 1.9, 3: 2.3, 4: 9.5, 5: 2.0}
    f2 = {1: 1.5, 2: 1.6, 3: 1.45, 4: 1.55, 5: 1.5}
    meas = {}
    lines = ["replicate,condition,protein,normalized_value"]
    for r in reps:
        for p, folds, base in (("CASP3", f1, 1.0), ("HSP90", f2, 1.3)):
            for c, f in (("Control", 1.0), ("Treated", folds[r])):
                v = round(noisy(gain[r] * base * f, 0.03), 4)
                meas[(r, c, p)] = v
                lines.append("R%d,%s,%s,%s" % (r, c, p, v))
    emit(lines, "caspase_five_repeats.csv")
    def per_rep(p):
        return [meas[(r, "Treated", p)] / meas[(r, "Control", p)] for r in reps]
    def cv(vals):
        return statistics.stdev(vals) / statistics.fmean(vals)
    v1 = per_rep("CASP3")
    v2 = per_rep("HSP90")
    med = statistics.median(v1)
    worst = max(range(len(v1)), key=lambda i: abs(v1[i] - med))
    kept = [v for i, v in enumerate(v1) if i != worst]
    planted["casp3_high_variability"] = cv(v1) > 0.5
    planted["hsp90_high_variability"] = cv(v2) > 0.5
    planted["most_discrepant"] = "R%d" % reps[worst]
    planted["casp3_mean_all"] = statistics.fmean(v1)
    planted["casp3_mean_excluding"] = statistics.fmean(kept)

print(json.dumps(planted))

