import json, os, csv, statistics

T = "/task"
names = set(os.listdir(T))
res = {}

def rows(fn):
    with open(os.path.join(T, fn), newline="") as fh:
        return list(csv.DictReader(fh))

def highest_linear(pairs, tol=0.15):
    pairs = sorted(pairs)
    slope = pairs[0][1] / pairs[0][0]
    best = pairs[0][0]
    for L, D in pairs:
        if abs(D / (slope * L) - 1.0) <= tol:
            best = L
    return best

if "antibody_dilution_series.csv" in names:
    rr = rows("antibody_dilution_series.csv")
    loads = [float(r["load_ug"]) for r in rr]
    g = [(float(r["load_ug"]), float(r["GAPDH_density"])) for r in rr]
    m = [(float(r["load_ug"]), float(r["MDM2_density"])) for r in rr]
    hg = highest_linear(g)
    hm = highest_linear(m)
    res["gapdh_highest_linear_load_ug"] = hg
    res["mdm2_highest_linear_load_ug"] = hm
    res["gapdh_loses_proportionality"] = hg < max(loads)
    res["mdm2_loses_proportionality"] = hm < max(loads)

if "hypoxia_panel.csv" in names:
    d = {}
    reps = []
    for r in rows("hypoxia_panel.csv"):
        d[(r["replicate"], r["condition"], r["protein"])] = float(r["density"])
        if r["replicate"] not in reps:
            reps.append(r["replicate"])
    def per_tp(rep, c, p):
        return d[(rep, c, p)] / d[(rep, c, "TotalProteinStain")]
    def changed(p):
        base = statistics.fmean([per_tp(rep, "Normoxia", p) for rep in reps])
        late = statistics.fmean([per_tp(rep, "Hypoxia_48h", p) for rep in reps])
        return abs(late / base - 1.0) > 0.15
    def ldha_fold(c):
        return statistics.fmean([per_tp(rep, c, "LDHA") / per_tp(rep, "Normoxia", "LDHA") for rep in reps])
    res["gapdh_changes_with_treatment"] = changed("GAPDH")
    res["actb_changes_with_treatment"] = changed("ACTB")
    res["ldha_fold_hypoxia_24h"] = ldha_fold("Hypoxia_24h")
    res["ldha_fold_hypoxia_48h"] = ldha_fold("Hypoxia_48h")

if "background_blot.csv" in names:
    raw = {}
    sub = {}
    for r in rows("background_blot.csv"):
        key = (r["condition"], r["protein"])
        rd = float(r["raw_band_density"])
        bg = float(r["band_area_px"]) * float(r["local_background_per_px"])
        raw[key] = rd
        sub[key] = rd - bg
    def norm_fold(p):
        a = sub[("Treated", p)] / sub[("Treated", "GAPDH")]
        b = sub[("Control", p)] / sub[("Control", "GAPDH")]
        return a / b
    def disagree(p):
        return (raw[("Treated", p)] / raw[("Control", p)] > 1.0) != (norm_fold(p) > 1.0)
    res["cdkn1a_normalized_fold"] = norm_fold("CDKN1A")
    res["ccnd1_normalized_fold"] = norm_fold("CCND1")
    res["cdkn1a_raw_and_corrected_disagree"] = disagree("CDKN1A")
    res["ccnd1_raw_and_corrected_disagree"] = disagree("CCND1")

if "bax_four_repeats.csv" in names:
    d = {}
    reps = []
    for r in rows("bax_four_repeats.csv"):
        d[(r["replicate"], r["condition"], r["protein"])] = float(r["raw_intensity"])
        if r["replicate"] not in reps:
            reps.append(r["replicate"])
    usable = []
    missing = []
    lc_missing = []
    for rep in reps:
        if all((rep, c, "BAX") in d for c in ("Control", "Treated")) and all((rep, c, "GAPDH") in d for c in ("Control", "Treated")):
            a = d[(rep, "Treated", "BAX")] / d[(rep, "Treated", "GAPDH")]
            b = d[(rep, "Control", "BAX")] / d[(rep, "Control", "GAPDH")]
            usable.append(a / b)
        else:
            missing.append(rep)
        if not all((rep, c, "GAPDH") in d for c in ("Control", "Treated")):
            lc_missing.append(rep)
    res["incomplete_replicate"] = missing[0] if missing else "none"
    res["all_target_bands_detected"] = len(missing) == 0
    res["all_loading_control_bands_detected"] = len(lc_missing) == 0
    res["mean_fold_usable_repeats"] = statistics.fmean(usable)
    res["n_usable_repeats"] = float(len(usable))

if "two_protein_replicates.csv" in names:
    d = {}
    reps = []
    for r in rows("two_protein_replicates.csv"):
        d[(r["replicate"], r["condition"], r["protein"])] = float(r["normalized_value"])
        if r["replicate"] not in reps:
            reps.append(r["replicate"])
    def per_rep(p):
        return [d[(rep, "Treated", p)] / d[(rep, "Control", p)] for rep in reps]
    def pooled(p):
        t = statistics.fmean([d[(rep, "Treated", p)] for rep in reps])
        c = statistics.fmean([d[(rep, "Control", p)] for rep in reps])
        return t / c
    for p, key in (("STAT3", "stat3"), ("TUBB", "tubb")):
        m = statistics.fmean(per_rep(p))
        res[key + "_mean_fold"] = m
        res[key + "_order_matters"] = abs(pooled(p) / m - 1.0) > 0.10

if "caspase_five_repeats.csv" in names:
    d = {}
    reps = []
    for r in rows("caspase_five_repeats.csv"):
        d[(r["replicate"], r["condition"], r["protein"])] = float(r["normalized_value"])
        if r["replicate"] not in reps:
            reps.append(r["replicate"])
    def per_rep(p):
        return [d[(rep, "Treated", p)] / d[(rep, "Control", p)] for rep in reps]
    def cv(vals):
        return statistics.stdev(vals) / statistics.fmean(vals)
    v1 = per_rep("CASP3")
    v2 = per_rep("HSP90")
    med = statistics.median(v1)
    worst = max(range(len(v1)), key=lambda i: abs(v1[i] - med))
    kept = [v for i, v in enumerate(v1) if i != worst]
    res["casp3_high_variability"] = cv(v1) > 0.5
    res["hsp90_high_variability"] = cv(v2) > 0.5
    res["most_discrepant_replicate"] = reps[worst]
    res["casp3_mean_fold_all_repeats"] = statistics.fmean(v1)
    res["casp3_mean_fold_excluding_discrepant"] = statistics.fmean(kept)

with open("/work/results.json", "w") as fh:
    json.dump(res, fh)
